template.solver:
def solve(n, s):
    for L in range(1, s + 1):
        divs = [d for d in range(1, L + 1) if L % d == 0]
        prev = [False] * (s + 1)
        prev[0] = True
        for k in range(n):
            cur = [False] * (s + 1)
            for t in range(s + 1):
                if prev[t]:
                    for d in divs:
                        if t + d <= s:
                            cur[t + d] = True
            prev = cur
        if prev[s]:
            return L
    return s
